import{_ as i,C as o,o as l,c as s,a2 as c,E as t,w as a,a as d}from"./chunks/framework.CZcFxxdw.js";const x=JSON.parse('{"title":"线程生命周期与 RAII","description":"从 std::thread 创建到 RAII 包装，掌握 C++ 线程的所有权语义与生命周期管理","frontmatter":{"title":"线程生命周期与 RAII","description":"从 std::thread 创建到 RAII 包装，掌握 C++ 线程的所有权语义与生命周期管理"},"headers":[],"relativePath":"vol5-concurrency/ch01-thread-lifecycle-raii/index.md","filePath":"vol5-concurrency/ch01-thread-lifecycle-raii/index.md","lastUpdated":null}'),h={name:"vol5-concurrency/ch01-thread-lifecycle-raii/index.md"};function p(_,e,f,u,I,m){const r=o("ChapterLink"),n=o("ChapterNav");return l(),s("div",null,[e[4]||(e[4]=c('<h1 id="线程生命周期与-raii" tabindex="-1">线程生命周期与 RAII <a class="header-anchor" href="#线程生命周期与-raii" aria-label="Permalink to &quot;线程生命周期与 RAII&quot;">​</a></h1><p>上一篇我们了解了 CPU cache 和 OS 线程的底层机制，现在终于可以动手写第一个多线程程序了。但在敲下 <code>std::thread t(...)</code> 之前，我们需要先想清楚一件事：线程是一种<strong>资源</strong>，它占用操作系统内核对象、栈空间、TLS 存储等。跟文件句柄、动态内存一样，线程也必须被正确地获取和释放——否则你要面对的就是 <code>std::terminate</code> 和资源泄漏。</p><p>这一章我们从 <code>std::thread</code> 的基础用法开始，逐步深入参数传递的陷阱、所有权转移的语义，最后用 RAII 把这些复杂性封装起来。目标是让多线程代码和单线程代码一样，拥有清晰的所有权和确定性的资源释放。</p><h2 id="本章内容" tabindex="-1">本章内容 <a class="header-anchor" href="#本章内容" aria-label="Permalink to &quot;本章内容&quot;">​</a></h2>',4)),t(n,{variant:"sub"},{default:a(()=>[t(r,{href:"01-std-thread"},{default:a(()=>[...e[0]||(e[0]=[d("std::thread 基础",-1)])]),_:1}),t(r,{href:"02-thread-arguments-and-lifetime"},{default:a(()=>[...e[1]||(e[1]=[d("线程参数与生命周期",-1)])]),_:1}),t(r,{href:"03-thread-ownership-and-raii"},{default:a(()=>[...e[2]||(e[2]=[d("线程所有权与 RAII",-1)])]),_:1}),t(r,{href:"04-thread-local-and-call-once"},{default:a(()=>[...e[3]||(e[3]=[d("thread_local 与 call_once",-1)])]),_:1})]),_:1})])}const A=i(h,[["render",p]]);export{x as __pageData,A as default};
